/**
 * Sound Lab playback on phones: each layer is a looping WAV generated by
 * ./synth (cached on the device, so it works offline), played with expo-audio.
 *
 * - Background: the audio session allows background playback (iOS
 *   UIBackgroundModes=audio and the Android foreground service come from the
 *   expo-audio config plugin); the lock-screen entry keeps Android playing.
 * - Interruptions (a call, another app): the system pauses the players; the
 *   engine reports "paused" and the person resumes. Nothing restarts by itself.
 * - Fades: volume is ramped in small steps (no clicks), also for timers.
 */
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { isRunningInExpoGo } from 'expo';
import * as FileSystem from 'expo-file-system/legacy';

import { encodeWav, fadeAt, mixGains, renderAsync, SoundSpec, specKey, toBase64, toInt16 } from './synth';

export interface Layer {
  id: string;
  spec: SoundSpec;
  volume: number;
}

export type EngineState = 'stopped' | 'loading' | 'playing' | 'paused';

const DIR = `${FileSystem.cacheDirectory}sound/`;
// Expo Go has no expo-audio lock-screen service (development builds and the
// store app do, from the config plugin): there the call only logs an error.
// (Constants.executionEnvironment did not say "storeClient" in Expo Go 58.)
const LOCK_SCREEN = !isRunningInExpoGo();

const inflight = new Map<string, Promise<string>>();

/** The WAV for a sound on this device (generated once; one generation at a time per sound). */
export function soundFile(spec: SoundSpec): Promise<string> {
  const key = specKey(spec);
  let job = inflight.get(key);
  if (!job) {
    job = makeSoundFile(spec, key).finally(() => inflight.delete(key));
    inflight.set(key, job);
  }
  return job;
}

async function makeSoundFile(spec: SoundSpec, key: string): Promise<string> {
  const path = `${DIR}${key}.wav`;
  const info = await FileSystem.getInfoAsync(path);
  if (info.exists && (info as any).size > 44) return path;
  await FileSystem.makeDirectoryAsync(DIR, { intermediates: true }).catch(() => {});
  const pcm = await renderAsync(spec);
  const wav = encodeWav(toInt16(pcm), pcm.sampleRate);
  // Written under a temporary name first: an interrupted write never leaves a broken sound behind.
  await FileSystem.writeAsStringAsync(`${path}.part`, toBase64(wav), { encoding: FileSystem.EncodingType.Base64 });
  await FileSystem.moveAsync({ from: `${path}.part`, to: path });
  return path;
}

/**
 * Generates the sounds of a mix in the background (one after another, in small
 * slices), so Play starts at once. Failures are ignored here: Play tries again.
 */
export async function prepareSounds(specs: SoundSpec[]) {
  for (const spec of specs) await soundFile(spec).catch(() => {});
}

/** Generated sounds (deleted with "delete all data"; regenerated when needed). */
export async function clearSoundCache() {
  await FileSystem.deleteAsync(DIR, { idempotent: true }).catch(() => {});
}

class NativeEngine {
  private players = new Map<string, { layer: Layer; player: AudioPlayer; sub?: { remove(): void } }>();
  private master = 0.5;
  private level = 1; // fade multiplier 0..1
  private fadeTimer: ReturnType<typeof setInterval> | null = null;
  state: EngineState = 'stopped';
  private listeners = new Set<(s: EngineState) => void>();
  private title = 'BeHappy';
  /** Bumped by every setLayers/stop: a layer that finishes generating late never joins a newer mix. */
  private gen = 0;
  /** Fade-in of layers that join while playing (0..1 per layer). */
  private entry = new Map<string, number>();
  private entryTimer: ReturnType<typeof setInterval> | null = null;

  onState(fn: (s: EngineState) => void) {
    this.listeners.add(fn);
    return () => {
      this.listeners.delete(fn);
    };
  }
  private set(s: EngineState) {
    this.state = s;
    this.listeners.forEach((fn) => fn(s));
  }

  private apply() {
    const entries = [...this.players.values()];
    const gains = mixGains(
      entries.map((e) => e.layer.volume),
      this.master
    );
    entries.forEach((e, i) => {
      e.player.volume = gains[i] * this.level * (this.entry.get(e.layer.id) ?? 1);
    });
  }

  /** Layers whose sound is already generated on this device. */
  async readyLayers(layers: Layer[]): Promise<Layer[]> {
    const out: Layer[] = [];
    for (const l of layers) {
      const info = await FileSystem.getInfoAsync(`${DIR}${specKey(l.spec)}.wav`).catch(() => null);
      if (info?.exists && (info as any).size > 44) out.push(l);
    }
    return out;
  }

  /** A layer joining a playing mix fades in over 2.5 s instead of appearing at once. */
  private fadeIn(id: string) {
    this.entry.set(id, 0);
    if (this.entryTimer) return;
    this.entryTimer = setInterval(() => {
      for (const [k, v] of this.entry) {
        if (v >= 1) this.entry.delete(k);
        else this.entry.set(k, Math.min(1, v + 0.02));
      }
      this.apply();
      if (!this.entry.size && this.entryTimer) {
        clearInterval(this.entryTimer);
        this.entryTimer = null;
      }
    }, 50);
  }

  /** background: add the missing layers quietly (no "loading" state), fading each in when ready. */
  async setLayers(layers: Layer[], title?: string, opts: { background?: boolean } = {}) {
    const gen = ++this.gen;
    if (title) this.title = title;
    const keep = new Set(layers.map((l) => l.id));
    for (const [id, e] of this.players) {
      if (keep.has(id)) continue;
      e.sub?.remove();
      e.player.remove();
      this.players.delete(id);
    }
    const wasPlaying = this.state === 'playing';
    for (const layer of layers) {
      const existing = this.players.get(layer.id);
      if (existing && specKey(existing.layer.spec) === specKey(layer.spec)) {
        existing.layer = layer;
        continue;
      }
      if (existing) {
        existing.sub?.remove();
        existing.player.remove();
      }
      if (wasPlaying && !opts.background) this.set('loading');
      const uri = await soundFile(layer.spec);
      if (gen !== this.gen) return; // a newer mix (or a stop) took over
      const player = createAudioPlayer({ uri });
      player.loop = true;
      player.volume = 0;
      const sub = player.addListener('playbackStatusUpdate', (st: any) => {
        // Paused by the system (interruption) while we think we're playing.
        if (this.state === 'playing' && st && st.playing === false && st.isLoaded && !st.isBuffering && this.level > 0) {
          const anyPlaying = [...this.players.values()].some((p) => p.player.playing);
          if (!anyPlaying) this.set('paused');
        }
      });
      this.players.set(layer.id, { layer, player, sub });
      if (opts.background) {
        this.fadeIn(layer.id);
        if (this.state === 'playing') player.play();
      } else if (wasPlaying) player.play();
      this.apply();
    }
    this.apply();
    if (wasPlaying && !opts.background) this.set('playing');
  }

  setVolume(id: string, volume: number) {
    const e = this.players.get(id);
    if (e) e.layer = { ...e.layer, volume };
    this.apply();
  }

  setMaster(v: number) {
    this.master = v;
    this.apply();
  }

  async play(fadeMs = 1500) {
    if (!this.players.size) return;
    await setAudioModeAsync({ playsInSilentMode: true, shouldPlayInBackground: true, interruptionMode: 'doNotMix' }).catch(() => {});
    const first = [...this.players.values()][0];
    if (LOCK_SCREEN) {
      try {
        first.player.setActiveForLockScreen(true, { title: this.title, artist: 'BeHappy' });
      } catch {
        // without it Android stops background playback after a few minutes
      }
    }
    if (this.state !== 'paused') this.level = 0;
    this.players.forEach((e) => e.player.play());
    this.set('playing');
    await this.fadeTo(1, fadeMs);
  }

  async pause() {
    await this.fadeTo(0, 400);
    this.players.forEach((e) => e.player.pause());
    this.set('paused');
  }

  async stop(fadeMs = 1500) {
    this.gen += 1;
    if (this.state === 'playing') await this.fadeTo(0, fadeMs);
    this.entry.clear();
    this.players.forEach((e) => {
      e.sub?.remove();
      if (LOCK_SCREEN) {
        try {
          e.player.setActiveForLockScreen(false);
        } catch {
          // ignore
        }
      }
      e.player.remove();
    });
    this.players.clear();
    this.level = 1;
    this.set('stopped');
  }

  fadeTo(target: number, ms: number): Promise<void> {
    if (this.fadeTimer) clearInterval(this.fadeTimer);
    const from = this.level;
    const started = Date.now();
    return new Promise((resolve) => {
      if (ms <= 0) {
        this.level = target;
        this.apply();
        resolve();
        return;
      }
      this.fadeTimer = setInterval(() => {
        const elapsed = Date.now() - started;
        this.level = fadeAt(from, target, elapsed, ms);
        this.apply();
        if (elapsed >= ms) {
          if (this.fadeTimer) clearInterval(this.fadeTimer);
          this.fadeTimer = null;
          resolve();
        }
      }, 50);
    });
  }
}

export const soundEngine = new NativeEngine();
